import { getCustomer } from './customers.js';
import { invoiceTotals } from './invoices.js';
import { balanceDue } from './payments.js';

function formatEuros(cents) {
  return (cents / 100).toFixed(2);
}

function escapeCsv(field) {
  if (field === null || field === undefined) {
    return '';
  }

  const str = String(field);

  if (str.includes(',') || str.includes('"') || str.includes('\n')) {
    return '"' + str.replace(/"/g, '""') + '"';
  }

  return str;
}

/**
 * Export invoices as CSV.
 * @param {Array} invoices - Invoices to export
 * @returns {string} CSV content with header and data rows
 */
export function exportCsv(invoices) {
  const lines = ['number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due'];

  for (const invoice of invoices) {
    const customerResult = getCustomer(invoice.customerId);
    const customerName = customerResult.ok ? customerResult.value.name : '';

    const { subtotal, discount, vat, total } = invoiceTotals(invoice);
    const due = balanceDue(invoice);

    const fields = [
      invoice.number || '',
      customerName,
      invoice.issueDate || '',
      invoice.dueDate || '',
      invoice.status || '',
      formatEuros(subtotal),
      formatEuros(discount),
      formatEuros(vat),
      formatEuros(total),
      formatEuros(due),
    ];

    const row = fields.map(escapeCsv).join(',');
    lines.push(row);
  }

  return lines.join('\n') + '\n';
}

